const progress=document.querySelector('.progress');function updateProgress(){const max=document.documentElement.scrollHeight-innerHeight;progress.style.width=(max>0?scrollY/max*100:0)+'%'}addEventListener('scroll',updateProgress,{passive:true});addEventListener('resize',updateProgress);updateProgress();
const descriptions={'1':['桥友消息','让经验交流拥有独立空间，方便找到正在沟通的桥友。'],'4':['企业消息','将简历沟通与面试邀约集中呈现，方便跟进求职进展。'],'5':['系统消息','集中呈现作品集修改、简历更新和面试提醒，让下一步行动更清楚。']};const tabs=[...document.querySelectorAll('[role=tab]')];function selectTab(tab){tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===tab));t.tabIndex=t===tab?0:-1});const id=tab.dataset.screen;document.querySelector('#message-screen').src='assets/screen-'+id+'.png';document.querySelector('#message-screen').alt=descriptions[id][0]+'界面';document.querySelector('#message-description').textContent=descriptions[id][1]}tabs.forEach((tab,i)=>{tab.tabIndex=i===0?0:-1;tab.addEventListener('click',()=>selectTab(tab));tab.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();let j=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;selectTab(tabs[j]);tabs[j].focus()}})});
const viewer=document.querySelector('#viewer');document.querySelectorAll('[data-image]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#viewer-image').src='assets/screen-'+button.dataset.image+'.png';document.querySelector('#viewer-image').alt=button.dataset.title;document.querySelector('#viewer-title').textContent=button.dataset.title;viewer.showModal()}));document.querySelector('.close').addEventListener('click',()=>viewer.close());viewer.addEventListener('click',e=>{if(e.target===viewer){const r=viewer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)viewer.close()}});
